#include "ark/surface_edit_059c.hpp"
#include "ark/serialize.hpp"
#include <iostream>
#include <stdexcept>
using namespace ark;
using V=arkjson::Value;
static unsigned checks=0;
static void check(bool ok,const std::string& why){++checks;if(!ok)throw std::runtime_error(why);}
static V json(const char* s){V v;check(arkjson::parse(s,v),"Fixture JSON");return v;}
static const V& field(const V& a,const char* k){const auto* p=a.find(k);if(!p)throw std::runtime_error(std::string("Missing ")+k);return *p;}
static V call(AgentSession& s,const char* tool,const V& args){const auto r=s.call(tool,args);check(!field(r,"isError").b,r.dump());return field(r,"structuredContent");}
static void rejected(AgentSession& s,V args){const auto before=documentToJson(s.document);check(field(s.call("surface_control",args),"isError").b,"Invalid control request accepted");check(before==documentToJson(s.document),"Rejected request changed CAD");}
int main(){try{
    AgentSession s;s.suppressFailureCapture();s.suppressIterationHistory();call(s,"doc_apply",json(R"({"commands":[{"op":"feature.add","type":"bspline_surface","name":"Control surface","native":{"poles":[[[0,0,0],[0,20,0]],[[30,0,0],[30,20,4]]]},"p":{"u_degree":1,"v_degree":1}},{"op":"feature.add","type":"native_solid","name":"Exact target","native":{"op":"box"},"p":{"width":5,"depth":5,"height":5}}]})"));
    auto inspect=json(R"({"action":"inspect","id":1})");inspect.set("expected_revision",V::makeNum((double)s.revision));const auto baseline=documentToJson(s.document);const auto net=call(s,"surface_control",inspect);check(field(net,"poles").arr.size()==4,"Exact net inventory");check(documentToJson(s.document)==baseline,"Inspect changes source");
    auto stretch=inspect;stretch.set("action",V::makeStr("stretch_plan"));stretch.set("source_brep_sha256",field(net,"source_brep_sha256"));stretch.set("max_displacement_mm",V::makeNum(10));stretch.set("edits",json(R"([{"u":1,"v":1,"delta_mm":[0,0,3]}])"));const auto plan=call(s,"surface_control",stretch);check(s.revision==1&&documentToJson(s.document)==baseline,"Plan changed source/revision");check(field(field(plan,"evidence"),"basis_preserved").b,"Plan lacks native evidence");const auto preview=call(s,"doc_preview",field(field(plan,"preview"),"arguments"));check(s.revision==1&&documentToJson(s.document)==baseline,"Preview changed source/revision");
    auto invalid=stretch;invalid.set("expected_revision",V::makeNum(0));rejected(s,invalid);invalid=stretch;invalid.set("source_brep_sha256",V::makeStr("stale"));rejected(s,invalid);invalid=inspect;invalid.set("unknown",V::makeBool(true));rejected(s,invalid);
    std::string targetHash;for(const auto& b:s.document.evalBodies)if(b.id==2)targetHash=field(*b.nativeData.find("topology"),"brep_sha256").str;check(!targetHash.empty(),"Target exact fingerprint");auto candidates=inspect;candidates.set("action",V::makeStr("candidates"));candidates.set("source_brep_sha256",field(net,"source_brep_sha256"));candidates.set("target_id",V::makeNum(2));candidates.set("target_brep_sha256",V::makeStr(targetHash));candidates.set("u",V::makeNum(0));candidates.set("v",V::makeNum(0));candidates.set("max_distance_mm",V::makeNum(10));const auto matches=call(s,"surface_control",candidates);check(!field(matches,"candidates").arr.empty(),"No exact target candidates");auto glue=candidates;glue.set("action",V::makeStr("glue_plan"));glue.set("max_displacement_mm",V::makeNum(10));glue.set("target_vertex",field(field(matches,"candidates").arr[0],"target_vertex"));glue.set("tangent_axis",V::makeStr("none"));const auto gluePlan=call(s,"surface_control",glue);const auto& command=field(gluePlan,"commands").arr[0];check(field(command,"inputs").arr.size()==2,"Target dependency omitted");check(!field(field(command,"native"),"glue").find("target_brep"),"Recipe embedded stale B-rep");call(s,"doc_preview",field(field(gluePlan,"preview"),"arguments"));check(documentToJson(s.document)==baseline,"Glue planning/preview changed source");invalid=glue;invalid.set("target_brep_sha256",V::makeStr("stale"));rejected(s,invalid);
    V apply=V::makeObj();apply.set("expected_revision",V::makeNum((double)s.revision));apply.set("candidate_id",field(preview,"candidate_id"));call(s,"doc_apply",apply);check(s.revision==2&&s.document.features.size()==3,"Publish failed");check(s.document.features.back().nativeSpec.find("op")->str=="deform_poles","Recipe not persisted");Document restored;std::string error;check(documentFromJson(documentToJson(s.document),restored,&error),error);restored.recompute();check(restored.evalBodies.size()==3,"Recompute lost deformed surface");
    const auto committed=documentToJson(s.document);auto badEdit=json(R"({"commands":[{"op":"feature.edit","id":1,"native":{"poles":[[[0,0,0],[0,20,0]],[[30,0,0],[30,20,5]]]}}]})");badEdit.set("expected_revision",V::makeNum((double)s.revision));check(field(s.call("doc_apply",badEdit),"isError").b,"Stale source dependency silently retargeted");check(documentToJson(s.document)==committed,"Stale dependency changed document");
    std::cout<<checks<<" surface-control host checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
